import sys

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        x = int(input[index])
        y = int(input[index + 1])
        index += 2
        if x == y:
            results.append("1 1")
        elif y % x != 0:
            results.append("0 0")
        else:
            b = y // x
            a = 1
            while y % b == 0 and y != x:
                y //= b
                a += 1
            if y == x:
                results.append(f"{a} {b}")
            else:
                results.append("0 0")
    print("\n".join(results))

if __name__ == "__main__":
    main()
